using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// The hook against the running game: rows recorded by tools/hook-parity.js on 2026-10-06. Three
    /// inert lungers, the player at (300, 400) holding the hook, fireAlt at the aim, then each tick the
    /// player phase (which runs the fields) and the projectile phase; "Early" right-clicks again at tick
    /// 60 to detonate it in flight. Every 10 ticks, per body: x, y, hp, stun, kvx, kvy, hookStacks,
    /// hitFlash; then the live fields and shells. The pull, the hold, the field's drain and suck, the
    /// resistance charge.
    /// </summary>
    [TestFixture]
    public sealed class HookParityTests
    {
        static void Check(double aimX, double aimY, int early, int ticks, int jitterDraws, int runDraws, object[][] rows)
        {
            var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
            run.state = "playing";
            run.CurrentRoom!.Secret = null;
            var p = run.player;
            p.x = p.lagX = 300; p.y = p.lagY = 400; p.altMode = "hook"; p.altCooldown = 0; p.hp = p.maxHp = 8;
            var bodies = new System.Collections.Generic.List<Enemy>();
            foreach (var (x, y) in new[] { (520.0, 280.0), (560.0, 330.0), (500.0, 350.0) })
            {
                var e = Enemy.Of(BodyKind.Lunger, x, y);
                e.noticeTimer = 1000000000;
                run.enemies.Add(e); bodies.Add(e);
            }
            int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls, row = 0;
            Weapons.FireAlt(run, aimX, aimY);
            for (int t = 1; t <= ticks; t++)
            {
                if (early > 0 && t == early) Weapons.FireAlt(run, aimX, aimY);
                TickOrder.TickPlayer(run, Input.None);
                TickOrder.TickProjectiles(run);
                if (t % 10 != 0) continue;
                var w = rows[row++];
                for (int i = 0; i < bodies.Count; i++)
                {
                    var e = bodies[i]; int o = 1 + i * 8; string at = " (body " + i + ", tick " + t + ")";
                    if (w[o] is string) { Assert.That(run.enemies, Does.Not.Contain(e), "should be dead" + at); continue; }
                    double D(int k) => System.Convert.ToDouble(w[o + k]);
                    Assert.That(e.x, Is.EqualTo(D(0)).Within(1e-6), "x" + at);
                    Assert.That(e.y, Is.EqualTo(D(1)).Within(1e-6), "y" + at);
                    Assert.That(e.hp, Is.EqualTo(D(2)).Within(1e-6), "hp" + at);
                    Assert.That(e.stun, Is.EqualTo(D(3)).Within(1e-6), "stun" + at);
                    Assert.That(e.kvx, Is.EqualTo(D(4)).Within(1e-6), "kvx" + at);
                    Assert.That(e.kvy, Is.EqualTo(D(5)).Within(1e-6), "kvy" + at);
                    Assert.That(e.hookStacks, Is.EqualTo((int)D(6)), "hookStacks" + at);
                    Assert.That(e.hitFlash, Is.EqualTo(D(7)).Within(1e-6), "hitFlash" + at);
                }
                int n = 1 + bodies.Count * 8;
                Assert.That(run.hookFields.Count, Is.EqualTo(System.Convert.ToInt32(w[n])), "fields at tick " + t);
                Assert.That(run.projectiles.Count, Is.EqualTo(System.Convert.ToInt32(w[n + 1])), "shells at tick " + t);
            }
            Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "jitter draws");
            Assert.That(run.rng.RunCalls - r0, Is.EqualTo(runDraws), "run draws");
        }

